// Distribution entry of @moritzbrantner/nlp-stack-wasm/text-index-wasm. Mirrors
// packages/text-index-wasm/index.js of the pinned nlp-stack commit; only the WASM initialization
// differs: the glue and the inlined .wasm bytes (generated by `bun run build`) are imported
// statically, so Bun and browser bundles need no separately served .wasm file.
import initWasm, * as bindings from "./pkg/moenarch_text_index_wasm.js";
import wasmBytes from "./pkg/wasm-bytes.js";

let wasmModulePromise;

export async function init() {
  wasmModulePromise ??= initWasm({ module_or_path: wasmBytes }).then(() => bindings);
  return wasmModulePromise;
}

export async function packageSurface() {
  const module = await init();
  return fromWasm(module.packageSurface());
}

export async function runOperation(request) {
  const module = await init();
  return fromWasm(module.runOperation(request));
}

function fromWasm(value) {
  if (value instanceof Map) {
    return Object.fromEntries(Array.from(value.entries(), ([key, entry]) => [key, fromWasm(entry)]));
  }
  if (Array.isArray(value)) {
    return value.map(fromWasm);
  }
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, fromWasm(entry)]));
  }
  return value;
}
